    let url = url.to_string();
    self.background_executor().spawn(async move {
        let keyring = oo7::Keyring::new().await?;
        keyring.unlock().await?;

        let items = keyring.search_items(&vec![("url", &url)]).await?;

        for item in items.into_iter() {
